.checkbox {
  line-height: 1;
  position: relative;
  padding-left: 0;
}
.checkbox label {
  display: inline-block;
  vertical-align: middle;
  position: relative;
  padding-left: 0;
  margin-bottom: 0;
  font-weight: normal;
}
.checkbox label::before {
  content: "�";
  position: relative;
  z-index: 1;
  left: 0;
  width: 17px;
  height: 17px;
  display: inline-block;
  vertical-align: middle;
  color: transparent;
  background-color: #ffffff;
  margin: 1px;
  margin-right: 5px;
  padding: 4px 3px;
  font-size: 11px;
  line-height: 1;
  border-radius: 4px;
  -webkit-transition: border 0.15s ease-in-out, color 0.15s ease-in-out;
  -o-transition: border 0.15s ease-in-out, color 0.15s ease-in-out;
  transition: border 0.15s ease-in-out, color 0.15s ease-in-out;
}
.checkbox label::after {
  position: absolute;
  top: 0;
  left: 0;
  width: 20px;
  height: 20px;
  content: "�";
  color: transparent;
  border: 1px solid #d9d9d9;
  border-radius: 4px;
}
.checkbox input[type=checkbox],
.checkbox input[type=radio] {
  position: absolute;
  z-index: 2;
  top: 0;
  left: 0;
  display: block;
  width: 100%;
  height: 100%;
  margin: 0;
  cursor: pointer;
  opacity: 0;
}
.checkbox input[type=checkbox]:focus + label::before,
.checkbox input[type=radio]:focus + label::before {
